#include "SimulationRunner.h"
#include "core/Psychrometrics.h"
#include <fstream>
#include <iomanip>
#include <stdexcept>
namespace ventilation::simulation {
void writeDashboard(const std::vector<SimulationResult>& results,const std::filesystem::path& path) {
    std::ofstream f(path);
    if(!f) throw std::runtime_error("Cannot write dashboard");
    f << R"HTML(<!doctype html><html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pince · Szárítási szimulátor</title><style>
:root{--bg:#f3f4ef;--card:#fff;--ink:#17342e;--muted:#65776f;--line:#dbe3dc;--teal:#147d64;--orange:#d38831;--red:#b3413b}*{box-sizing:border-box}body{margin:0;background:var(--bg);font:14px/1.5 system-ui,Segoe UI,sans-serif;color:var(--ink)}header{background:#163b30;color:#e9f4e9;padding:25px 4vw;display:flex;justify-content:space-between;align-items:center}header small{letter-spacing:2px;color:#9bc7b0;font-size:11px}header h1{font-size:26px;margin:4px 0 0;font-weight:550}header .tag{border:1px solid #547563;border-radius:30px;padding:8px 16px;color:#c8e5d4;font-size:12px}main{max-width:1540px;margin:auto;padding:24px 4vw}.toolbar{display:flex;justify-content:space-between;gap:18px;align-items:center;margin-bottom:18px}select,button,a.button{border:1px solid #cbd8ce;border-radius:8px;padding:10px 14px;background:white;color:var(--ink);font:inherit;cursor:pointer}select{min-width:330px}a.button{text-decoration:none}.intro h2{margin:0 0 3px;font-size:23px;font-weight:600}.intro p{color:var(--muted);margin:0}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:20px 0}.metric{background:white;border:1px solid var(--line);border-radius:12px;padding:16px 19px}.metric .k{color:var(--muted);font-size:11px;letter-spacing:1px;text-transform:uppercase}.metric strong{display:block;font-size:29px;font-weight:550;margin:4px 0}.metric small{color:var(--muted)}.workspace{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:20px}.playback{background:#e3ece4;border-radius:11px;padding:14px 18px;display:flex;align-items:center;gap:15px;margin-bottom:16px}.playback input{width:100%;accent-color:var(--teal)}.playback b{white-space:nowrap;font-variant-numeric:tabular-nums}.plots{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.plot{background:white;border:1px solid var(--line);border-radius:12px;padding:14px 14px 8px;min-width:0}.plot h3{font-size:13px;margin:0 0 4px}.legend{font-size:11px;color:var(--muted);margin-bottom:3px}.legend span{margin-right:12px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:4px}canvas{width:100%;height:150px;display:block;cursor:crosshair}.side{background:white;border:1px solid var(--line);border-radius:12px;padding:19px;height:fit-content;position:sticky;top:16px}.side h3{margin:0;font-size:15px}.livehead{display:flex;align-items:center;justify-content:space-between;margin-bottom:15px}.badge{font-size:11px;background:#e4f2e9;color:#147d64;padding:4px 8px;border-radius:6px}.status{font-size:16px;font-weight:600;margin:10px 0}.reason{color:var(--muted);font-size:11px;overflow-wrap:anywhere;border-bottom:1px solid var(--line);padding-bottom:14px}.readings{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:15px 0}.readings small{color:var(--muted)}.readings strong{display:block;font-size:20px}.device{padding:11px 0;border-bottom:1px solid var(--line)}.device b{float:right}.tank{height:8px;background:#edf1ed;border-radius:5px;overflow:hidden;margin-top:8px}.tank div{height:100%;background:var(--orange);width:0}.warn{background:#fff0dd;color:#8d4f12;border-radius:8px;padding:10px;font-size:12px;margin-top:12px}.events{max-height:190px;overflow:auto;font-size:11px;color:var(--muted);margin-top:15px}.events div{padding:4px 0;border-bottom:1px solid #eef1ed}.note{color:var(--muted);font-size:12px;margin:22px 0;max-width:950px}.foot{border-top:1px solid var(--line);padding:17px 0;color:var(--muted);font-size:11px}.mono{font-variant-numeric:tabular-nums}@media(max-width:1000px){.workspace{grid-template-columns:1fr}.side{position:static}.metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){header{padding:20px}header h1{font-size:21px}header .tag{display:none}main{padding:20px}.toolbar{align-items:stretch;flex-direction:column}select{width:100%;min-width:0}.plots{grid-template-columns:1fr}.metric strong{font-size:24px}}
</style></head><body><header><div><small>PINCE LAB / WINDOWS · 0.3.0</small><h1>Szárítás, mérhető döntésekkel.</h1></div><div class="tag">Offline szimuláció · valós core logika</div></header><main><div class="toolbar"><select id="scenario" aria-label="Forgatókönyv"></select><div><a class="button" id="csv" download>CSV letöltése ↗</a></div></div><section class="intro"><h2 id="title"></h2><p id="description"></p><p id="parameters" style="margin-top:8px;font-size:12px"></p></section><div class="metrics" id="metrics"></div><div class="workspace"><div><div class="playback"><button id="play" aria-label="Lejátszás">▶</button><input type="range" id="cursor" min="0" value="0" aria-label="Szimuláció időpontja"><b id="time"></b></div><div class="plots" id="plots"></div></div><aside class="side"><div class="livehead"><h3>Pillanatkép</h3><span class="badge" id="badge">AUTO</span></div><div class="status" id="state"></div><div class="reason" id="reason"></div><div class="readings" id="readings"></div><div class="device">Ventilátor <b id="fan"></b></div><div class="device">Konnektor <b id="socket"></b></div><div class="device">Kompresszor <b id="compressor"></b></div><div class="device">Visszajelzés <b id="feedback"></b></div><div class="device">Valódi modelltartály <b id="tank"></b><div class="tank"><div id="fill"></div></div></div><div id="warning"></div><div class="events" id="events"></div></aside></div><p class="note">A pince vízgőztömegét számoljuk; az RH levezetett érték. A tartályszint itt a szimulált készülék tényleges szintje, a szaggatott vonal külön, csak tájékoztató becslés. A hő- és vízkivonási modellek egyszerűsítettek, nem a konkrét pince vagy készülék hitelesített előrejelzései.</p><div class="foot" id="balance"></div></main><script>const data=)HTML";
    auto str=[&](const std::string& s) { f<<'"'; for(char c:s) { if(c=='"' || c=='\\') f<<'\\'; if(c=='\n') f<<"\\n"; else f<<c; } f<<'"'; };
    auto number=[&](double x) { if(std::isfinite(x)) f<<x; else f<<"null"; };
    f<<std::setprecision(10)<<'[';
    bool first=true;
    for(const auto& r:results) {
        if(!first) f<<','; first=false;
        f<<"{\"id\":"; str(r.scenario.id); f<<",\"title\":"; str(r.scenario.title);
        f<<",\"description\":"; str(r.scenario.description);
        f<<",\"summary\":["<<r.fanHours<<','<<r.dehumCommandHours<<','<<r.compressorHours<<','<<r.extractedLiters
            <<','<<r.generatedLiters<<','<<r.netVentilationLiters<<','<<r.condensedLiters<<','<<r.massBalanceErrorGram
            <<','<<r.firstTankFullSeconds<<','<<r.averageBasementRH<<','<<r.maximumBasementRH<<','<<r.minimumBasementTemperature
            <<','<<r.timeAbove70RH<<','<<r.timeAbove80RH<<','<<r.timeBelowMinimumTemperature<<','<<r.cumulativeEnergyKWh
            <<','<<r.tankFullEventCount<<"],\"parameters\":["<<r.configuration.basementVolumeM3<<','<<r.configuration.ventilationAirflowM3h
            <<','<<r.configuration.moistureIngressGPerHour<<','<<r.configuration.dehumidifier.referenceExtractionLh
            <<','<<r.configuration.dehumidifier.powerWatts<<','<<r.configuration.dehumidifier.tankCapacityLiters
            <<','<<r.configuration.ventilationPowerW<<"],\"mode\":";
        str(r.scenario.mode==Mode::Auto?"AUTO":r.scenario.mode==Mode::On?"MANUAL_VENTILATION":r.scenario.mode==Mode::Off?"MANUAL_OFF":"MANUAL_DEHUMIDIFIER");
        f<<",\"rows\":[";
        bool rowFirst=true;
        for(const auto& v:r.rows) {
            if(!rowFirst) f<<','; rowFirst=false;
            const auto b=psychrometrics::calculate(v.basement.temperatureC,v.basement.humidityRH);
            const auto o=psychrometrics::calculate(v.outside.temperatureC,v.outside.humidityRH);
            f<<'['<<static_cast<double>(v.timestamp)/3600000<<','<<v.basement.temperatureC<<','<<v.basement.humidityRH
                <<','<<b->absoluteHumidityGm3<<','; number(b->dewPointC.value_or(NAN)); f<<',';
            number(v.outside.valid?v.outside.temperatureC:NAN); f<<','; number(v.outside.valid?v.outside.humidityRH:NAN); f<<',';
            number(v.outside.valid?o->absoluteHumidityGm3:NAN); f<<','; number(v.outside.valid?o->dewPointC.value_or(NAN):NAN); f<<',';
            number(v.output.differenceGm3);
            f<<','<<v.output.ventilationRequested<<','<<v.output.dehumidifierRequested<<','; str(feedbackName(v.feedback.feedback));
            f<<','<<v.powerWatts<<','<<v.tankLiters<<','<<v.tankFull<<','; str(stateName(v.output.state));
            f<<','; str(v.output.reason);
            f<<','<<v.compressorRunning<<','<<v.output.estimatedTankLevelLiters<<','<<v.output.dehumidifierIneffective<<','<<v.outside.valid
                <<','<<v.ventilationWaterRemovalGPerHour<<','<<v.dehumidifierWaterRemovalGPerHour
                <<','<<v.cumulativeVentilationWaterRemovedL<<','<<v.cumulativeDehumidifierWaterRemovedL<<','<<v.cumulativeEnergyKWh<<']';
        }
        f<<"]}";
    }
    f << R"HTML(];
const $=id=>document.getElementById(id), green='#147d64',orange='#d38831',blue='#688ead';
const specs=[['Hőmérséklet','°C',[[1,'Pince',green],[5,'Kültér',orange]]],['Relatív páratartalom','%',[[2,'Pince',green],[6,'Kültér',orange]]],['Abszolút nedvesség','g/m³',[[3,'Pince',green],[7,'Kültér',orange]]],['Szárítási előny · Δ AH','g/m³',[[9,'Pince − kültér',green]]],['Szellőztetés','BE / KI',[[10,'Ventilátor',green]],true],['Páramentesítő','BE / KI',[[11,'Konnektor',orange],[18,'Kompresszor',blue]],true],['Víztartály','L',[[14,'Valódi modell',orange],[19,'ESTIMATED',blue]]],['Teljesítményfelvétel','W',[[13,'Páramentesítő · FELTÉTELEZETT W',green]],true],['Tényleges vízkivonás az előző intervallumban','g/h',[[22,'Légcsere (nettó)',green],[23,'Páramentesítő',orange]]],['Elszámolt kumulatív villamos energia','kWh',[[26,'Ventilátor nélkül, ha W ismeretlen',green]]]];
let selected=0,index=0,playing=false,timer;
data.forEach((s,i)=>{const o=document.createElement('option');o.value=i;o.textContent=s.title;$('scenario').append(o)});
specs.forEach((s,i)=>{let p=document.createElement('section');p.className='plot';p.innerHTML=`<h3>${s[0]}</h3><div class="legend">${s[2].map(t=>`<span><i class="dot" style="background:${t[2]}"></i>${t[1]}</span>`).join('')}<span>${s[1]}</span></div><canvas id="chart${i}" role="img" aria-label="${s[0]}"></canvas>`;$('plots').append(p);p.querySelector('canvas').addEventListener('pointerdown',e=>{const c=e.currentTarget,b=c.getBoundingClientRect(),rows=data[selected].rows;index=Math.round(Math.max(0,Math.min(1,(e.clientX-b.left-34)/(b.width-47)))*(rows.length-1));update()})});
const fmt=(n,d=1)=>n==null?'—':Number(n).toFixed(d),clock=h=>`${Math.floor(h).toString().padStart(2,'0')}:${Math.floor((h%1)*60+1e-5).toString().padStart(2,'0')}`;
const states={IDLE:'Nincs szárítási igény',VENTILATING:'Szellőztetés',DEHUMIDIFYING:'Páramentesítés',SENSOR_ERROR:'Szenzorhiba',DEHUMIDIFIER_ERROR:'Páramentesítő hiba',WAITING_MINIMUM_OFF_TIME:'Védelmi várakozás',MANUAL_OFF:'Manuális KI'};
function choose(){selected=+$('scenario').value;const s=data[selected],m=s.summary,p=s.parameters;index=Math.min(60,s.rows.length-1);$('title').textContent=s.title;$('description').textContent=s.description;$('parameters').textContent=`V=${p[0]} m³ · Q=${p[1]} m³/h · forrás=${p[2]} g/h · referencia=${p[3]} L/h · ${p[4]} W (SIMULATION ASSUMPTION) · ${p[6]>0?'ventilátorfogyasztás: '+p[6]+' W':'ventilátorfogyasztás ismeretlen / energia-részösszeg'}`;$('csv').href=s.id+'.csv';$('cursor').max=s.rows.length-1;$('metrics').innerHTML=[['Szellőztetés',fmt(m[0])+' h','Összes ventilátor BE idő'],['Kompresszor',fmt(m[2])+' h','Konnektor BE: '+fmt(m[1])+' h'],['Tartályba kivont víz',fmt(m[3],2)+' L','Tényleges modellkivonás'],['Légcserével elvitt víz',fmt(m[5],2)+' L','Nettó vízgőz-export'],['Átlag / maximum RH',fmt(m[9])+' / '+fmt(m[10])+'%','Idővel súlyozott átlag'],['Minimum pince T',fmt(m[11])+' °C','Küszöb alatt: '+fmt(m[14])+' h'],['Elszámolt energia',fmt(m[15],2)+' kWh',p[6]>0?'Páramentesítő és ventilátor':'Páramentesítő; ventilátor nélkül'],['Tele tartály esemény',String(m[16]),'Kondenzátum: '+fmt(m[6],2)+' L']].map(a=>`<div class="metric"><span class="k">${a[0]}</span><strong>${a[1]}</strong><small>${a[2]}</small></div>`).join('');$('balance').textContent=`Nedvességforrás: ${fmt(m[4],3)} L · Kondenzátum: ${fmt(m[6],3)} L · Mérlegeltérés: ${m[7].toExponential(2)} g · Első megtelt tartály: ${m[8]<0?'nem telt meg':clock(m[8]/3600)} · 70% fölött: ${fmt(m[12])} h · 80% fölött: ${fmt(m[13])} h · Minden grafikon azonos időtengelyt használ.`;let events=[],last='';s.rows.forEach(r=>{if(r[16]!==last){events.push(`<div>${clock(r[0])} · ${states[r[16]]||r[16]}</div>`);last=r[16]}});$('events').innerHTML='<b>Állapotváltások</b>'+events.join('');update()}
function update(){const r=data[selected].rows[index];$('cursor').value=index;$('time').textContent=clock(r[0]);$('state').textContent=states[r[16]]||r[16];$('reason').textContent=r[17];$('badge').textContent=r[16].includes('ERROR')?'HIBA':data[selected].mode==='AUTO'?'AUTO':'MANUÁLIS';$('badge').style.background=r[16].includes('ERROR')?'#fbe4df':'#e4f2e9';$('readings').innerHTML=`<div><small>PINCE</small><strong>${fmt(r[1])} °C</strong>${fmt(r[2])}% · ${fmt(r[3],2)} g/m³<br><small>DP ${fmt(r[4])} °C</small></div><div><small>KÜLTÉR</small><strong>${fmt(r[5])} °C</strong>${fmt(r[6])}% · ${fmt(r[7],2)} g/m³<br><small>DP ${fmt(r[8])} °C</small></div>`;$('fan').textContent=r[10]?'BE':'KI';$('socket').textContent=r[11]?'BE':'KI';$('compressor').textContent=r[18]?'MŰKÖDIK':'ÁLL';$('feedback').textContent=r[12];$('tank').textContent=fmt(r[14],2)+' / '+data[selected].parameters[5]+' L';$('fill').style.width=Math.min(100,r[14]/data[selected].parameters[5]*100)+'%';let warnings=[];if(r[15])warnings.push('A modelltartály megtelt. A konnektor BE állapota nem bizonyít működést.');if(r[20])warnings.push('Páramentesítés nem hatékony.');if(!r[21])warnings.push('Kültéri szenzor offline: mindkét AUTO kimenet KI.');if(r[16]==='DEHUMIDIFIER_ERROR')warnings.push('Ellenőrizd a tartályt / készüléket / tápellátást.');$('warning').innerHTML=warnings.map(w=>`<div class="warn">${w}</div>`).join('');specs.forEach((s,i)=>draw(i,s))}
function draw(i,s){const c=$('chart'+i),b=c.getBoundingClientRect(),dpr=window.devicePixelRatio||1,w=b.width,h=b.height;c.width=w*dpr;c.height=h*dpr;const ctx=c.getContext('2d');ctx.scale(dpr,dpr);let rows=data[selected].rows,vals=rows.flatMap(r=>s[2].map(t=>r[t[0]])).filter(Number.isFinite),lo=vals.reduce((a,v)=>Math.min(a,v),Infinity),hi=vals.reduce((a,v)=>Math.max(a,v),-Infinity);if(i===4||i===5){lo=0;hi=1.1}else{let pad=Math.max((hi-lo)*.12,.1);lo-=pad;hi+=pad;if(i===6||i===7||i===9)lo=0}const l=34,rr=w-13,top=8,bot=h-25,x=t=>l+t/rows.at(-1)[0]*(rr-l),y=v=>bot-(v-lo)/(hi-lo)*(bot-top);ctx.font='10px Segoe UI';ctx.lineWidth=1;for(let j=0;j<4;j++){let v=lo+(hi-lo)*j/3,yy=y(v);ctx.strokeStyle='#edf0eb';ctx.beginPath();ctx.moveTo(l,yy);ctx.lineTo(rr,yy);ctx.stroke();ctx.fillStyle='#84938a';ctx.fillText(v.toFixed(i===7?0:1),0,yy+3)}for(let j=0;j<=4;j++){let t=rows.at(-1)[0]*j/4;ctx.fillText(fmt(t,0)+'h',x(t)-6,h-7)}s[2].forEach((series,k)=>{ctx.strokeStyle=series[2];ctx.lineWidth=1.8;ctx.setLineDash(i===6&&k===1?[4,4]:[]);ctx.beginPath();let prev=null;rows.forEach(r=>{const v=r[series[0]];if(v==null){prev=null;return}if(prev===null)ctx.moveTo(x(r[0]),y(v));else{if(s[3])ctx.lineTo(x(r[0]),y(prev));ctx.lineTo(x(r[0]),y(v))}prev=v});ctx.stroke()});ctx.setLineDash([3,4]);ctx.strokeStyle='#70877a';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x(rows[index][0]),top);ctx.lineTo(x(rows[index][0]),bot);ctx.stroke();ctx.setLineDash([])}
$('scenario').addEventListener('change',choose);$('cursor').addEventListener('input',()=>{index=+$('cursor').value;update()});$('play').addEventListener('click',()=>{playing=!playing;$('play').textContent=playing?'Ⅱ':'▶';clearInterval(timer);if(playing)timer=setInterval(()=>{index=(index+5)%data[selected].rows.length;update()},150)});window.addEventListener('resize',update);choose();
</script></body></html>)HTML";
    if(!f) throw std::runtime_error("Dashboard write failed");
}
}
